INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('1', 'yes-no', 'Как Вы думаете, этот вопрос был составлен человеком или сгенерирован машиной?', '{"noText": "человек", "noValue": "0", "yesText": "машина", "yesValue": "1"}', 'IsCreatedByHuman', '{"kind": "AFTER_EACH"}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('2', 'single-choice', 'Какова ваша реакция на первый вопрос?', '[{"id": "0", "text": "запутанно и страшно"}, {"id": "1", "text": "решать можно, но тяжело"}, {"id": "2", "text": "могло быть полегче, но удалось решить"}, {"id": "3", "text": "справился(-лась) с вопросом без особых трудностей"}, {"id": "4", "text": "было скучно, хотелось поинтереснее"}]', 'StrategyFeedbackSurvey', '{"kind": "AFTER_FIRST"}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('3', 'single-choice', 'Как вы оцениваете сложность этого вопроса?', '[{"id": "1", "text": "слишком сложно"}, {"id": "2", "text": "сложно"}, {"id": "3", "text": "средне"}, {"id": "4", "text": "легко"}, {"id": "5", "text": "слишком легко"}, {"id": "contains_errors", "text": "этот вопрос содержит ошибки"}, {"id": "unknown_tokens", "text": "я не понял(-а) этот вопрос из-за странных конструкций"}]', 'StrategyFeedbackSurvey', '{"kind": "AFTER_EACH"}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('4', 'single-choice', 'Как вы оцениваете время, необходимое для решения этого вопроса?', '[{"id": "1", "text": "слишком долго"}, {"id": "2", "text": "долго"}, {"id": "3", "text": "средне"}, {"id": "4", "text": "быстро"}, {"id": "5", "text": "очень быстро"}]', 'StrategyFeedbackSurvey', '{"kind": "AFTER_EACH"}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('5', 'single-choice', 'Было ли заметно возрастание / убывание сложности за последние 3-5 вопросов?', '[{"id": "1", "text": "быстрое убывание сложности"}, {"id": "2", "text": "медленное убывание сложности"}, {"id": "3", "text": "изменений не заметно"}, {"id": "4", "text": "медленное возрастание сложности"}, {"id": "5", "text": "быстрое возрастание сложности"}, {"id": "cant_evaluate", "text": "трудно оценить"}]', 'StrategyFeedbackSurvey', '{"kind": "AFTER_SPECIFIC", "numbers": [3, 6, 9, 12, 15, 18, 21]}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('6', 'single-choice', 'Соответствует ли изменение сложности вашим предшествующим действиям (упрощает вопросы когда вам трудно и вы делаете ошибки, усложняет когда легко)?', '[{"id": "1", "text": "сложность как правило меняется соответственно"}, {"id": "2", "text": "сложность чаще меняется соответственно, чем нет"}, {"id": "3", "text": "нет, связь не заметна"}, {"id": "4", "text": "сложность чаще меняется наоборот"}, {"id": "5", "text": "сложность как правило меняется наоборот"}]', 'StrategyFeedbackSurvey', '{"kind": "AFTER_SPECIFIC", "numbers": [3, 6, 9, 12, 15, 18, 21]}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('7', 'single-choice', 'Сколько вопросов было задано?', '[{"id": "1", "text": "слишком много"}, {"id": "2", "text": "больше, чем было необходимо для проверки и усвоения темы"}, {"id": "3", "text": "достаточно"}, {"id": "4", "text": "меньше, чем было необходимо для проверки и усвоения темы"}, {"id": "5", "text": "слишком мало"}]', 'StrategyFeedbackSurvey', '{"kind": "AFTER_LAST"}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('8', 'single-choice', 'Были ли повторяющиеся вопросы?', '[{"id": "not", "text": "нет, не было"}, {"id": "slightly", "text": "да, изредка"}, {"id": "many", "text": "да, много"}]', 'StrategyFeedbackSurvey', '{"kind": "AFTER_LAST"}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('9', 'single-choice', 'Насколько быстро система нашла удобную вам сложность вопросов?', '[{"id": "1", "text": "удобной мне сложности вопросов для обучения не было"}, {"id": "2", "text": "под конец упражнения"}, {"id": "3", "text": "в середине упражнения"}, {"id": "4", "text": "в начале упражнения"}, {"id": "5", "text": "сразу, с первого вопроса"}]', 'StrategyFeedbackSurvey', '{"kind": "AFTER_LAST"}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('10', 'single-choice', 'Считаете ли вы достаточной полноту покрытия изучаемой темы вопросами?', '[{"id": "1", "text": "нет, вопросов слишком мало"}, {"id": "2", "text": "да, вопросов разных видов хватает"}, {"id": "3", "text": "да, но вопросов было слишком много"}, {"id": "5", "text": "не хватает вопросов на какую-то тему (укажите в текстовом поле, какую)"}]', 'StrategyFeedbackSurvey', '{"kind": "AFTER_LAST"}', 1);
INSERT INTO `survey_questions` (`id`, `type`, `text`, `options_json`, `survey_id`, `policy`, `required`) VALUES ('11', 'open-ended', 'Хотите сообщить что-то ещё?', '{}', 'StrategyFeedbackSurvey', '{"kind": "AFTER_LAST"}', 0);
